"""Write RamanujanTau/Atkin11Seed/SData.lean: the H2 numerators S_i (i = g2, g3, g4, g6) as `PY` literals."""
import json
S = json.load(open('S.json'))
def je(dense):
    comps = []
    for r in range(5):
        c = dense[r::5]
        while c and c[-1] == 0: c = c[:-1]
        comps.append("[" + ", ".join(str(x) for x in c) + "]")
    return "⟨" + ", ".join(comps) + "⟩"
names = {"1": "S2", "2": "S3", "3": "S4", "4": "S6"}
out = ["/-", "# The H2 numerators: `P'(φ)·g = S(φ)` for `g = g₂, g₃, g₄, g₆`", "",
       "Generated by `scripts/atkin11/seeds/gen_data.py` from `S.json` (`compute_S.py`).", "-/",
       "import RamanujanTau.Atkin11Seed.JArith", "", "namespace Atkin11Seed", ""]
for k, nm in names.items():
    out.append(f"def {nm} : PY := [" + ",\n  ".join(je(row) for row in S[k]) + "]")
    out.append("")
out.append("/-- the numerator of `g_i` (`1, g₂, g₃, g₄, g₆`). -/")
out.append("def Snum : Nat → PY\n  | 0 => dP\n  | 1 => S2\n  | 2 => S3\n  | 3 => S4\n  | _ => S6")
out.append("")
out.append("end Atkin11Seed")
open('../../../RamanujanTau/Atkin11Seed/SData.lean', 'w').write("\n".join(out) + "\n")
